// app/thanks/page.tsx
//
// Static "Thanks" page for OpenBangla. The data lives in @/data/contributors.json,
// which is generated by `bun run update:contributors`. Never edit it by hand.
// Colors come from Fumadocs' `fd-*` Tailwind tokens, so light/dark mode follows
// your existing Fumadocs theme.

import type { Metadata } from "next";
import data from "@/data/contributors.json"; // adjust the alias if your tsconfig differs

export const metadata: Metadata = {
  title: "Thanks",
  description: "All-time contributors to OpenBangla.",
};

// Standard competition ranking: equal commit counts share a rank (1, 2, 2, 4 ...).
function withRanks(list: { name: string; commits: number }[]) {
  const sorted = [...list].sort((a, b) => b.commits - a.commits || a.name.localeCompare(b.name));
  return sorted.map((c, i) => ({
    ...c,
    rank: sorted.findIndex((x) => x.commits === c.commits) + 1,
    key: `${i}-${c.name}`,
  }));
}

export default function ThanksPage() {
  const rows = withRanks(data.contributors);
  const total = rows.reduce((sum, c) => sum + c.commits, 0);

  return (
    <main className="mx-auto w-full max-w-3xl px-4 py-12 sm:py-16">
      <header className="mb-8">
        <h1 className="text-3xl font-bold tracking-tight text-fd-foreground sm:text-4xl">Thanks</h1>
        <h2 className="mt-2 text-lg text-fd-muted-foreground">All-time OpenBangla contributors</h2>
        <p className="mt-4 text-fd-muted-foreground">
          OpenBangla exists because of the people below. Thank you for every commit. The list counts
          commits on the default branch of each repository in the OpenBangla organization, excluding
          merge commits.
        </p>

        <dl className="mt-6 flex flex-wrap gap-3">
          {[
            ["Contributors", rows.length],
            ["Commits", total],
            ["Repositories", data.repositories],
          ].map(([label, value]) => (
            <div key={label} className="rounded-lg border border-fd-border bg-fd-card px-4 py-3">
              <dt className="text-sm text-fd-muted-foreground">{label}</dt>
              <dd className="text-2xl font-semibold text-fd-card-foreground">{value}</dd>
            </div>
          ))}
        </dl>
      </header>

      <div className="overflow-hidden rounded-xl border border-fd-border bg-fd-card">
        <table className="w-full border-collapse text-left text-sm">
          <caption className="sr-only">OpenBangla contributors ranked by commit count</caption>
          <thead className="bg-fd-muted text-fd-muted-foreground">
            <tr>
              <th scope="col" className="w-16 px-4 py-2.5 font-medium">
                Rank
              </th>
              <th scope="col" className="px-4 py-2.5 font-medium">
                Name
              </th>
              <th scope="col" className="px-4 py-2.5 text-right font-medium">
                Commits
              </th>
            </tr>
          </thead>
          <tbody>
            {rows.map((c) => (
              <tr
                key={c.key}
                className="border-t border-fd-border transition-colors hover:bg-fd-accent/50"
              >
                <td className="px-4 py-2.5 tabular-nums text-fd-muted-foreground">{c.rank}</td>
                <td className="px-4 py-2.5 text-fd-card-foreground">
                  <span>{c.name}</span>
                  {c.name.endsWith("[bot]") && (
                    <span className="ml-2 rounded border border-fd-border px-1.5 py-0.5 text-xs text-fd-muted-foreground">
                      bot
                    </span>
                  )}
                </td>
                <td className="px-4 py-2.5 text-right font-medium tabular-nums text-fd-foreground">
                  {c.commits}
                </td>
              </tr>
            ))}
          </tbody>
        </table>
      </div>

      <p className="mt-6 text-sm text-fd-muted-foreground">
        Last updated on{" "}
        <time dateTime={data.updatedAt}>
          {new Date(`${data.updatedAt}T00:00:00Z`).toLocaleDateString("en-US", {
            year: "numeric",
            month: "long",
            day: "numeric",
            timeZone: "UTC",
          })}
        </time>
        . This site is static, so the list is refreshed by hand.
      </p>
    </main>
  );
}
